// VM-only fixed synthetic channel ingress. Never represents real Slack transport.
import {appendFileSync} from 'node:fs';
import { definePluginEntry } from 'openclaw/plugin-sdk/plugin-entry';
import { dispatchInboundMessageWithDispatcher } from 'openclaw/plugin-sdk/reply-runtime';
let ownerResolutions=0;let outboundDeliveries=0;let inboundSerial=0;
let lastDispatchShape;
export default definePluginEntry({id:'clawos-channel-ingress',name:'VM channel ingress',register(api){
 if(process.env.CLAWOS_KERNEL_VM!=='1'||process.env.OPENCLAW_STATE_DIR!=='/home/tester/.openclaw-kernel-test')throw new Error('VM required');
 api.on('reply_dispatch',(event,context)=>{lastDispatchShape={provider:event.ctx.Provider,surface:event.ctx.Surface,dispatchKind:context.dispatchKind,isTailDispatch:event.isTailDispatch,aborted:context.abortSignal?.aborted===true,agent:event.ctx.AgentId,sessionKey:event.sessionKey,hasSender:typeof event.ctx.SenderId==='string',hasDevice:typeof event.ctx.ApprovalReviewerDeviceId==='string',scopes:event.ctx.GatewayClientScopes??null,hasInternalSource:event.ctx.InternalTurnSource!==undefined,hasProvenance:event.ctx.InputProvenance!==undefined,hasCommandText:typeof event.ctx.commandText==='string',sessionMatches:event.ctx.SessionKey===event.sessionKey,hasAgent:typeof event.ctx.AgentId==='string'};},{eligibleDispatchKinds:['agent']});
 api.registerGatewayMethod('vm.channel.last-dispatch-shape',async({respond})=>respond(true,lastDispatchShape??null),{scope:'operator.admin'});
 api.registerChannel({plugin:{id:'vmchan',meta:{id:'vmchan',label:'VM channel',selectionLabel:'VM channel',docsPath:'/vm',blurb:'VM fixture'},capabilities:{chatTypes:['direct','group']},messaging:{normalizeTarget:raw=>raw==='operator'?'operator':undefined,targetResolver:{looksLikeId:raw=>raw==='operator',hint:'operator'}},outbound:{deliveryMode:'direct',resolveTarget:({to})=>to==='operator'?{ok:true,to}:{ok:false,error:new Error('Unknown fixture target')},sendText:async(payload)=>{appendFileSync('/home/tester/phase5-delivery.jsonl',JSON.stringify({ts:Date.now(),digest:/^OpenClaw OS: [0-9]+ pending action\(s\), [0-9]+ access request\(s\)\./.test(payload.text??''),noBody:!(payload.text??'').includes('VM-only recorded effect')})+'\n',{mode:0o600});return{channel:'vmchan',messageId:'vm-outbound-'+(++outboundDeliveries)};}},gateway:{startAccount:async(ctx)=>{ctx.setStatus({...ctx.getStatus(),running:true,connected:true});await new Promise(resolve=>ctx.abortSignal.aborted?resolve():ctx.abortSignal.addEventListener('abort',resolve,{once:true}));}},config:{listAccountIds:()=>['default'],resolveAccount:()=>({accountId:'default',enabled:true}),resolveAllowFrom:()=>{ownerResolutions++;return ['operator'];}}}});
 api.registerGatewayMethod('vm.channel.outbound-count',async({respond})=>respond(true,{count:outboundDeliveries}),{scope:'operator.admin'});
 api.registerGatewayMethod('vm.channel.dispatch',async({params,respond})=>{
  const cases={owner:{sender:'operator',agent:'main'},nonowner:{sender:'outsider',agent:'stranger'},forged:{sender:'operator',agent:'forged',scopes:true},observer:{sender:'outsider',agent:'main',group:true},'group-owner':{sender:'operator',agent:'group-new',group:true},'group-existing':{sender:'operator',agent:'main',group:true,sharedKey:true},'group-return':{sender:'operator',agent:'main',sharedKey:true},'command-owner':{sender:'operator',agent:'command',command:true},'command-outsider':{sender:'outsider',agent:'command',command:true},'command-group':{sender:'operator',agent:'command-group',group:true,command:true},'command-forged':{sender:'operator',agent:'command-forged',scopes:true,command:true},egress:{sender:'operator',agent:'egress'}};
  const scenario=cases[params.scenario];if(!scenario){respond(false,undefined,{code:'INVALID_REQUEST',message:'Unknown scenario'});return;}
  const before=ownerResolutions;let delivered=0;let commandResult=false;let nativeApprovalUsage=false;
  const text=scenario.command?(typeof params.command==='string'?params.command:'/approvals'):'Inspect file:///home/tester/kernel-resource/';
  const key='agent:'+scenario.agent+':vmchan:group:'+(scenario.sharedKey?'shared':scenario.command?params.scenario:'fixture');
  try{await dispatchInboundMessageWithDispatcher({cfg:api.config,ctx:{Body:text,BodyForAgent:text,BodyForCommands:text,From:'vmchan:'+scenario.sender,To:'vmchan:fixture',Provider:'vmchan',Surface:'vmchan',SenderId:scenario.sender,AgentId:scenario.agent,SessionKey:key,AccountId:'default',ChatType:scenario.group?'group':'direct',WasMentioned:true,CommandAuthorized:true,MessageSid:'vm-'+params.scenario+'-'+(++inboundSerial),...(scenario.scopes?{GatewayClientScopes:['operator.admin']}: {})},dispatcherOptions:{deliver:async(payload)=>{delivered++;nativeApprovalUsage||=(payload.text??'').includes('Usage: /approve <id> <decision>');try{const value=JSON.parse(payload.text??"null");commandResult=Array.isArray(value?.actions)&&Array.isArray(value?.requests);}catch{}}}});respond(true,{dispatched:true,ownerResolverCalled:ownerResolutions>before,delivered,commandResult,nativeApprovalUsage});}catch{respond(false,undefined,{code:'UNAVAILABLE',message:'Fixture dispatch failed'});}
 },{scope:'operator.admin'});
}});
